sp_widget.client_script:
api.controller = function (DHManagerService, $scope, $http, snAnalytics, $timeout) {
  /**
   * TODO: Move specific Eco Logc into it's own factory/service
   * 1. Get Eco score
   * 2. Get country aggregates
   * 3. processing responses of HTTP calls
   * 4. Metric Comparisons
   */

  var c = this;
  var headlineStats = [
    "total_energy_consumption",
    "total_co2_emitted",
  ];

  c.loadingCountryMetrics = true;
  c.loading = true;
  c.countryMetrics = null;
  c.actions = null;
  c.ecoMetrics = null;
  c.eco_score = null;
  c.metricComparison = null;
  $scope.countryCollapsed = false;

  snAnalytics.startPage("dh_my_green_it", "My Green IT");

  DHManagerService.getMetrics().then(() => {
    $http.get("/api/x_mukl_dh/dh/eco-score").then(function (response) {
      $timeout(() => {
        c.eco_score = response?.data.score || null;
      }, 500);
    });
  });

  // Helper function to calculate metrics when both are available
  c.calculateMetricComparison = function () {
    if (!c.countryMetrics || !c.devices || c.metricComparison !== null) return;

    c.metricComparison = {};

    Object.keys(c.devices).forEach((assetId) => {
      const device = c.devices[assetId];

      if (!device.metrics) return;
      const comparison = {};

      device.metrics.forEach((metric) => {
        const countryMetric = c.countryMetrics.metrics.find(
          (m) => m.name === metric.name,
        );

        if (countryMetric) {
          const userValue = parseFloat(metric.value);
          const countryValue = parseFloat(countryMetric.value);
          const difference = userValue - countryValue;
          const percentDifference = ((difference / countryValue) * 100).toFixed(
            0,
          );

          comparison[metric.name] = {
            percentDifference: percentDifference,
            isOver: difference > 0,
          };
        }
        c.metricComparison[device.asset_id] = comparison;
      });
    });
  };

  //retrieve eco aggregates
  $http.get("/api/x_mukl_dh/dh/country-metrics").then(function (response) {
    c.countryMetrics = response.data.data;
    c.calculateMetricComparison();
    c.loadingCountryMetrics = false;
  });

  //TODO: we could remove this ion the future as the backend can now be targetted to ask specifically for ECO or Performance metrics and actions
  $scope.$watch(
    () => {
      return DHManagerService.state.assetDetails;
    },
    (newVal) => {
      if (!newVal) return;

      c.loading = true;

      for (let key in newVal) {
        const item = newVal[key];

        item.metrics = c.getEcoMetrics(item.metrics);
        item.actions = c.getEcoActions(item.actions);

        item.headlinestats = newVal[key]?.metrics?.filter((m, i) => {
          return headlineStats.includes(m.name);
        });
      }

      c.devices = newVal;
      c.calculateMetricComparison();
      c.loading = false;
    },
  );

  $scope.$watch(
    () => {
      return DHManagerService.state.selectedAsset;
    },
    (newVal) => {
      if (!newVal) return;
      c.selectedAsset = newVal;
    },
  );

  c.getEcoMetrics = function (metrics) {
    if (!metrics.length) return null;

    const ecoMetrics = metrics.filter((m) => {
      return m.category == "ECO";
    });

    return ecoMetrics;
  };

  c.getEcoActions = function (actions) {
    if (!actions.length) return null;

    return actions.filter((a) => {
      return a.category == "ECO";
    });
  };

  c.isNotHeadline = function (item) {
    return !headlineStats.some(
      (stat) => stat.toLowerCase() === item.name.toLowerCase(),
    );
  };

  c.valParse = function (val) {
    return parseFloat(val).toFixed(1);
  };

  c.executeAction = async function (device, action) {
    device.executeAction(action);
  };

  c.getIcon = function (action) {
    switch (action.type) {
      case "remote_action":
        return "fa-medkit";
      case "url":
      case "page":
        return "fa-external-link";
      case "client_script":
        return "fa-cogs";
      case "server_script":
        return "fa-cogs";
      default:
        return "fa-arrow-right";
    }
  };
};

sp_widget.css:
.actions-container {
  grid-auto-columns: 1fr;
  display: inline-grid;
  position: relative;
  overflow-x: auto;
  width: 100%;
  gap: 1rem;
  padding: 0 2rem 2rem 2rem;

  @media (min-width: $screen-sm-min) {
    grid-template-columns: repeat(3, 1fr);
  }
}

.stats {
  grid-auto-columns: 1fr;
  display: inline-grid;
  position: relative;
  overflow-x: auto;
  width: 100%;
  padding: 2rem;
  gap: 1.33rem;

  @media (min-width: $screen-sm-min) {
    grid-template-columns: repeat(2, 1fr);
  }

  @media (min-width: $screen-md-min) {
    grid-template-columns: repeat(4, 1fr);
  }

  &.country-stats {
    @media (min-width: $screen-md-min) {
      grid-template-columns: repeat(3, 1fr);
    }
  }

  .stat {
    grid-template-columns: repeat(1, 1fr);
    column-gap: 1rem;
    width: 100%;
    padding-block: 2rem;
    padding-inline: 2rem;
    display: inline-grid;
    border-radius: $border-radius-large;
    background-color: var(--bg-dynamic);

    .stat-figure {
      grid-row: 1 / span 3;
      grid-column-start: 2;
      place-self: center flex-end;
    }

    .stat-title {
      font-size: $font-size-small;
      white-space: nowrap;
      grid-column-start: 1;
      color: $text-secondary;
    }

    .stat-value {
      white-space: nowrap;
      grid-column-start: 1;
      font-size: $font-size-xxl;
      font-weight: 800;
      padding-block: 1rem;
    }

    .stat-desc {
      white-space: nowrap;
      color: $text-tertiary;
      grid-column-start: 1;
      font-size: $font-size-small;

      i {
        margin-right: 0.66rem;
      }
    }
  }
}

.text-primary {
  color: $brand-primary-darker;
}

.text-danger {
  color: $brand-danger-darker !important;
}
.text-success {
  color: $brand-success-darker !important;
}

.leaf-fill {
  fill: $brand-success-darker; /* green */
  transition:
    height 1s ease-in,
    y 1s ease-in;
}

.divider {
  white-space: nowrap;
  height: 1rem;
  margin: 0.66rem 0;
  --divider-color: lighten($text-muted, 33%);
  flex-direction: row;
  align-self: stretch;
  align-items: center;
  display: flex;

  &:before,
  &:after {
    content: "";
    background-color: var(--divider-color);
    flex-grow: 1;
    width: 100%;
    height: 0.125rem;
  }

  &:not(:empty) {
    gap: 1rem;
    padding: 0 2rem;
  }
}

.headline-stats {
  display: flex;
  flex-wrap: wrap;
  gap: 3rem;
  align-items: stretch;
  justify-content: center;
  padding: 2rem;
  width: 100%;

  .headline-stat {
    width: 250px;
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    gap: 1rem;

    .stat-title {
      flex: 1;
      text-align: center;
      width: 100%;
      display: flex;
      flex-direction: column;
      align-items: center;
      justify-content: center;
      height: 100%;

      .title {
        flex: 1;
        text-align: center;
        width: 100%;
        display: flex;
        flex-direction: column;
        align-items: center;
        justify-content: center;
        height: 100%;
        margin: 0;
      }
      small {
        color: $text-muted;
        font-size: $font-size-small;
      }
    }
    .value {
      display: flex;
      border-radius: 8px;
      background-color: var(--bg-dynamic);
      width: 100%;
      align-items: center;
      justify-content: space-between;
      padding: 2rem;
      gap: 1rem;
      font-weight: 800;
      flex: 1;

      .stat-value {
        font-size: $font-size-xxl;
      }
    }

    .description {
      color: $text-muted;
      font-size: $font-size-small;
      text-align: center;
      display: flex;
      gap: 0.66rem;
      place-items: center;
    }
  }
}

.nav.nav-tabs {
  border-bottom: 1px solid #dadde2;
  margin: 0 2rem -2px 2rem;
  transition: all 0.3s ease-in-out;

  &.loading {
    min-height: 2rem !important;
  }

  li {
    background-color: rgba(0, 0, 0, 0.05);
    border-top-right-radius: $panel-border-radius;
    border-top-left-radius: $panel-border-radius;
    overflow: hidden;
    color: $text-muted;
    margin-right: 0.33rem;
    width: 100%;
    
    @media (min-width: $screen-sm-min) {
      width: auto;
    }

    a {
      border: 0 !important;
      margin: 0;
      display: flex;
      flex-direction: column;
      padding: 2rem 1.33rem;

      .title {
        font-weight: bold;
        font-size: $font-size-base;
      }
      small {
        font-size: $font-size-small;
      }

      &:hover {
        color: $brand-primary !important;
      }
    }

    &.active {
      border: 1px solid $border-tertiary;
      border-bottom-width: 0 !important;
      margin-bottom: 0;

      a {
        background-color: $panel-bg;
        border-bottom-width: 0px !important;
        color: $brand-primary !important;
        border-color: $border-tertiary !important;
      }
    }
  }
}

.tab-content {
  .tab-pane {
    transition: all 0.3s ease-in-out;

    .tab-title {
      font-weight: bold;
      margin: 0;
      padding: 1rem 2rem;
    }
  }
}

.loading {
  min-height: 10rem;
  width: 100%;
  border-radius: 1rem;
  background-image: linear-gradient(
    to right,
    #f6f7f8 0%,
    #edeef1 20%,
    #f6f7f8 40%,
    #f6f7f8 100%
  );
  background-repeat: no-repeat;
  background-size: 100rem 28rem;
  animation: shimmer 2s infinite linear;
}

@keyframes shimmer {
  0% {
    background-position: -1000px 0;
  }

  100% {
    background-position: 1000px 0;
  }
}

#leafFill {
  animation: fillUp 4s ease-out forwards;
}

@keyframes fillUp {
  from {
    height: 0;
    y: 420; /* Bottom of leaf */
  }
  to {
    height: 60;
    y: 360; /* Top of leaf */
  }
}

.card {
  border-radius: $border-radius;
  outline-offset: 2px;
  outline: 0 solid transparent;
  flex-direction: column;
  transition: outline 0.2s ease-in-out;
  display: flex;
  position: relative;
  min-width: 25%;
}

.card .card-body {
  font-size: $font-size-base;
  padding: 1.33rem;
  //font-weight: 600;
  flex-direction: column;
  flex: auto;
  gap: 0.5rem;
  display: flex;
  background-color: rgba($brand-primary-lighter, 0.1);
  box-shadow: $sp-panel-box-shadow;

  > p {
    flex: 1;
  }
}

.card .card-title {
  align-items: center;
  gap: 0.5rem;
  font-weight: 900 !important;
  display: flex;

  h1,
  h2,
  h3,
  h4,
  h5 {
    font-weight: 900 !important;
  }
}

.card .card-actions {
  flex-wrap: wrap;
  align-items: flex-start;
  gap: 0.5rem;
  display: flex;
  justify-content: flex-end;
}

.country-eco-container {
  h3 {
    padding: 1rem 2rem;
  }
}

.eco-score {
  display: flex;
  align-items: center;
  gap: 2rem;
  margin-bottom: 3rem;

  .eco-leaf {
    display: grid;
    align-content: center;

    .leaf-fill {
      transition:
        height 1s cubic-bezier(0.23, 1, 0.32, 1),
        y 1s cubic-bezier(0.23, 1, 0.32, 1);
      fill: $brand-success !important;
    }

    svg {
      width: 12rem;
      height: auto;

      /* Tablet (Small devices, 768px and up) */
      @media (min-width: $screen-sm-min) {
        width: 18rem;
      }

      path {
        stroke: $brand-success-darker;
      }
    }
  }

  .eco-score-number {
    h5 {
      font-size: 2rem;
      color: $text-muted;
      margin: 0;
    }
    .score {
      font-size: 9rem;
      font-weight: 900;
      color: $brand-primary;
    }
    .out-of {
      color: $text-muted;
      font-size: 4.33rem;
    }
  }
}

sp_widget.link:
function link(scope, element, attrs, controller) {
  const leafFill = element[0].querySelector("#leafClip");
  const scoreDisplay = element[0].querySelector("#scoreDisplay");
  const originalY = 352.304;
  const maxHeight = 45;

  function updateLeafFill(percentage) {
    const fillHeight = (percentage / 100) * maxHeight;
    const newY = originalY + (maxHeight - fillHeight);

    leafFill.setAttribute("y", newY);
    leafFill.setAttribute("height", fillHeight);
  }

  function countUpEased(element, start, end, duration) {
    const range = end - start;
    const startTime = Date.now();

    function easeOutCubic(t) {
      return 1 - Math.pow(1 - t, 5); // Slower at the end
    }

    function update() {
      const elapsed = Date.now() - startTime;
      const progress = Math.min(elapsed / duration, 1);
      const easedProgress = easeOutCubic(progress);
      const current = start + range * easedProgress;

      element.textContent = Math.round(current);

      if (progress < 1) {
        requestAnimationFrame(update);
      }
    }

    requestAnimationFrame(update);
  }

  const unwatch = scope.$watch(
    () => controller.eco_score,
    (nval) => {
      if (!nval) return;

      updateLeafFill(nval);
      countUpEased(scoreDisplay, 0, nval, 1800);

      unwatch();
    },
  );
}
